{
  "autoMemoryDirectory": "/w/profile/memory",
  "cleanupPeriodDays": 3650,
  "hooks": {
    "PostToolUse": [
      {
        "matcher": "Task",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'test -n \"$HW_EVENT_SPOOL\" || exit 0; exec '\\''/usr/local/lib/agentd/agentd-proxy'\\'' '\\''hooks'\\'' '\\''claude'\\'' '\\''post-task'\\''' # harness-wrapper-hook:agentd"
          }
        ]
      },
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'test -n \"$HW_EVENT_SPOOL\" || exit 0; exec '\\''/usr/local/lib/agentd/agentd-proxy'\\'' '\\''hooks'\\'' '\\''claude'\\'' '\\''post-tool-use'\\''' # harness-wrapper-hook:agentd"
          }
        ]
      }
    ],
    "PostToolUseFailure": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'test -n \"$HW_EVENT_SPOOL\" || exit 0; exec '\\''/usr/local/lib/agentd/agentd-proxy'\\'' '\\''hooks'\\'' '\\''claude'\\'' '\\''post-tool-use-failure'\\''' # harness-wrapper-hook:agentd"
          }
        ]
      }
    ],
    "PreToolUse": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'test -n \"$HW_EVENT_SPOOL\" || exit 0; exec '\\''/usr/local/lib/agentd/agentd-proxy'\\'' '\\''hooks'\\'' '\\''claude'\\'' '\\''pre-tool-use'\\''' # harness-wrapper-hook:agentd"
          }
        ]
      }
    ],
    "SessionEnd": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'test -n \"$HW_EVENT_SPOOL\" || exit 0; exec '\\''/usr/local/lib/agentd/agentd-proxy'\\'' '\\''hooks'\\'' '\\''claude'\\'' '\\''session-end'\\''' # harness-wrapper-hook:agentd"
          }
        ]
      }
    ],
    "SessionStart": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'test -n \"$HW_EVENT_SPOOL\" || exit 0; exec '\\''/usr/local/lib/agentd/agentd-proxy'\\'' '\\''hooks'\\'' '\\''claude'\\'' '\\''session-start'\\''' # harness-wrapper-hook:agentd"
          }
        ]
      }
    ],
    "Stop": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'test -n \"$HW_EVENT_SPOOL\" || exit 0; exec '\\''/usr/local/lib/agentd/agentd-proxy'\\'' '\\''hooks'\\'' '\\''claude'\\'' '\\''stop'\\''' # harness-wrapper-hook:agentd"
          }
        ]
      }
    ],
    "SubagentStart": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'test -n \"$HW_EVENT_SPOOL\" || exit 0; exec '\\''/usr/local/lib/agentd/agentd-proxy'\\'' '\\''hooks'\\'' '\\''claude'\\'' '\\''subagent-start'\\''' # harness-wrapper-hook:agentd"
          }
        ]
      }
    ],
    "SubagentStop": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'test -n \"$HW_EVENT_SPOOL\" || exit 0; exec '\\''/usr/local/lib/agentd/agentd-proxy'\\'' '\\''hooks'\\'' '\\''claude'\\'' '\\''subagent-stop'\\''' # harness-wrapper-hook:agentd"
          }
        ]
      }
    ],
    "UserPromptSubmit": [
      {
        "matcher": "",
        "hooks": [
          {
            "type": "command",
            "command": "sh -c 'test -n \"$HW_EVENT_SPOOL\" || exit 0; exec '\\''/usr/local/lib/agentd/agentd-proxy'\\'' '\\''hooks'\\'' '\\''claude'\\'' '\\''user-prompt-submit'\\''' # harness-wrapper-hook:agentd"
          }
        ]
      }
    ]
  },
  "skipDangerousModePermissionPrompt": true
}
